{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "However, despite this wealth of genomic knowledge and consequent clinical benefits, equitable clinical research, provision of genomic treatment services and culturally safe, acceptable genomic diagnostic tools, the treatment options for global Indigenous populations have remained limited. The ability to harness precision medicine approaches to address ongoing health disparities within Indigenous populations is needed, but it requires research using culturally respectful approaches with Indigenous guidance to select appropriate methods to understand the true nature of the genetic variation of Indigenous populations. The diversity of ethnicity, race, and ancestry in the way that genetic knowledge is discovered, classified, and applied considerably limits efforts to achieve health equity and eliminate health disparities for Indigenous people. ... Inadequate sampling and representation of genetic diversity are widely recognized as a significant bias inherent in genomic databases, which has direct implications for the healthcare available to minority populations (Perera 2019).",
      "reason": "The introduction describes the current state of knowledge (advances in genomic medicine) and important uncertainties/biases (limited inclusion of Indigenous peoples, inadequate sampling, ethical/privacy concerns) that justify the review."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Background: This systematic review aims to highlight the scope of pharmacogenomics research within global Indigenous populations. This review also explores the barriers and facilitators of pharmacogenomics research within this population.",
      "reason": "The abstract explicitly states the aim and importance of the review—to highlight scope and explore barriers/facilitators—establishing the need for conducting the review given gaps in Indigenous genomics research."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence explicitly identifies existing similar systematic reviews or explains the need for the current review relative to prior reviews; no citations or statements comparing to earlier reviews were found in the provided chunks."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "This systematic review aims to highlight the scope of pharmacogenomics research within global Indigenous populations. This review also explores the barriers and facilitators of pharmacogenomics research within this population.",
      "reason": "The review focuses on scope, barriers, facilitators, and empirical pharmacogenomics/genomics research rather than evaluating intervention effects; therefore describing a mechanism of action for an intervention does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "This systematic review aims to highlight the scope of pharmacogenomics research within global Indigenous populations. This review also explores the barriers and facilitators of pharmacogenomics research within this population.",
      "reason": "The review is not assessing a complex intervention or delivery context and does not present or require a logic model; the focus is on describing research scope and barriers/facilitators, so a logic model is not applicable."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "This systematic review aimed to synthesize global empirical evidence involving Indigenous populations for genomics research with a particular focus on pharmacogenomics. The overarching intent of this review is to provide insight regarding how research has been conducted, the role of Indigenous participants in such research, and the benefits or outcomes achieved for Indigenous participants and/or communities.",
      "reason": "The manuscript explicitly states clear objectives describing the review aim and specific foci (synthesise empirical evidence, focus on pharmacogenomics, explore how research was conducted, role of participants, and benefits/outcomes). However, the objectives are not presented using a formal question-formulation framework (e.g., PICO, PICOS), so the reporting is partial against the criterion requiring a relevant framework."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_4",
      "quote": "This systematic review aimed to synthesize global empirical evidence involving Indigenous populations for genomics research with a particular focus on pharmacogenomics.",
      "reason": "The review is descriptive/synthesis of empirical genomics/pharmacogenomics research rather than a review of intervention effects requiring planned comparisons; therefore PICO-style planned comparisons are not applicable."
    }
  ],
  "confidence": 80
}

{
